//! Media pool (PRD M1–M4): import, bins, search, tags, thumbnails, analysis
//! progress, source info, dragging items onto the timeline, listening to
//! audio, and music, sound effects, voiceovers and videos generated by a
//! provider.

pub(crate) mod form;
mod generate;
mod hdr;
pub(crate) mod import;
mod thumbs;
mod video;
pub(crate) mod voiceover;

use crate::state::EditorState;
use crate::ui::MediaDrag;
use crate::ui::kit::theme as t;
use crate::ui::kit::{
    Button, ContextMenuExt as _, DialogExt as _, DropdownMenu as _, EmptyState, Icon, IconName,
    Input, PopupMenu, PopupMenuItem, ScrollableElement as _, Spinner, Tooltip, h_flex, v_flex,
};
use crate::ui::library::shared;
use flikk_core::command::Command;
use flikk_core::model::{Bin, MediaItem, MediaKind};
use flikk_core::services::{JobState, JobStatus};
use flikk_core::{BinId, MediaId, Time};
use gpui_kit::base::input::{InputEvent, InputState};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;
use std::cell::Cell;
use std::collections::HashMap;
use std::path::PathBuf;
use std::rc::Rc;
use std::sync::{Arc, Mutex};
use std::time::Duration;
use thumbs::Thumbs;

const POLL: Duration = Duration::from_millis(500);

/// Narrowest a grid tile gets before the grid drops a column.
const TILE: f32 = 100.;
/// Items area wide enough for the list's format and bin columns.
const WIDE_LIST: f32 = 420.;

actions!(media_pool, [RemoveSelected, ListenToSelected, FocusSearch]);

fn bind_keys(cx: &mut App) {
    static BOUND: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    if BOUND.swap(true, std::sync::atomic::Ordering::SeqCst) {
        return;
    }
    let c = Some("MediaPool");
    cx.bind_keys([
        KeyBinding::new("delete", RemoveSelected, c),
        KeyBinding::new("backspace", RemoveSelected, c),
        KeyBinding::new("space", ListenToSelected, c),
        KeyBinding::new("/", FocusSearch, Some("MediaPool && !Input")),
    ]);
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Layout {
    Grid,
    List,
}

pub struct MediaPoolPanel {
    state: Entity<EditorState>,
    focus: FocusHandle,
    search: Entity<InputState>,
    tag_input: Entity<InputState>,
    bin_input: Entity<InputState>,
    layout: Layout,
    /// `None` shows every item.
    bin: Option<BinId>,
    renaming: Option<BinId>,
    selected: Option<MediaId>,
    /// Items added to the selection with cmd/ctrl- or shift-click.
    also: Vec<MediaId>,
    thumbs: Thumbs,
    jobs: Vec<JobStatus>,
    /// Proxy creation progress, written from background threads.
    proxies: Arc<Mutex<HashMap<MediaId, f32>>>,
    /// Proxies already looked for, by path (see `hdr.rs`).
    hdr_proxies: std::collections::HashSet<std::path::PathBuf>,
    /// Files dragged in from outside, while they are over the items.
    dropping: Option<Vec<PathBuf>>,
    /// The items area's width last frame, for the grid's columns.
    width: Rc<Cell<Pixels>>,
    _subscriptions: Vec<Subscription>,
    _poll: Task<()>,
}

impl MediaPoolPanel {
    pub fn new(state: Entity<EditorState>, window: &mut Window, cx: &mut Context<Self>) -> Self {
        bind_keys(cx);
        let search = cx.new(|cx| InputState::new(window, cx).placeholder("Search media"));
        let tag_input = cx.new(|cx| InputState::new(window, cx).placeholder("Add tag"));
        let bin_input = cx.new(|cx| InputState::new(window, cx));
        let _subscriptions = vec![
            cx.observe(&state, |_, _, cx| cx.notify()),
            cx.subscribe(&search, |_, _, _: &InputEvent, cx| cx.notify()),
            cx.subscribe_in(&tag_input, window, |this, input, ev, window, cx| {
                if let InputEvent::PressEnter { .. } = ev {
                    let tag = input.read(cx).value().trim().to_owned();
                    input.update(cx, |i, cx| i.set_value("", window, cx));
                    this.add_tag(tag, cx);
                }
            }),
            cx.subscribe_in(&bin_input, window, |this, input, ev, _, cx| {
                if matches!(ev, InputEvent::PressEnter { .. } | InputEvent::Blur) {
                    let name = input.read(cx).value().trim().to_owned();
                    this.finish_rename(name, cx);
                }
            }),
        ];
        let _poll = cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor().timer(POLL).await;
                if this.update(cx, |this, cx| this.poll(cx)).is_err() {
                    break;
                }
            }
        });
        let selected = crate::demo::enabled()
            .then(|| state.read(cx).bus.project().media.first().map(|m| m.id))
            .flatten();
        if let Some(form) = crate::demo::generate_form() {
            cx.defer_in(window, move |this: &mut Self, window, cx| {
                match form.as_str() {
                    "voiceover" => this.open_voiceover(None, window, cx),
                    "voices" | "voices-describe" | "voices-audio" => {
                        let start = match form.as_str() {
                            "voices-describe" => crate::ui::voices::Start::Describe {
                                description: String::new(),
                            },
                            "voices-audio" => crate::ui::voices::Start::Clone {
                                files: Vec::new(),
                                name: String::new(),
                            },
                            _ => crate::ui::voices::Start::Find,
                        };
                        crate::ui::voices::open(this.state.clone(), start, None, window, cx)
                    }
                    "sfx" => this.open_generate(generate::Kind::SoundEffect, window, cx),
                    "video" => {
                        // Without a provider set, the first model fal offers.
                        let model = this.video_model(cx).or_else(|| {
                            let fal = flikk_cloud::provider("fal")?;
                            let first =
                                fal.offer(flikk_core::cloud::Capability::Video)?.models[0].id;
                            fal.api.video_model(first).cloned()
                        });
                        if let Some(model) = model {
                            this.open_video(model, window, cx);
                        }
                    }
                    _ => this.open_generate(generate::Kind::Music, window, cx),
                }
            });
        }
        Self {
            state,
            focus: cx.focus_handle(),
            search,
            tag_input,
            bin_input,
            layout: Layout::Grid,
            bin: None,
            renaming: None,
            selected,
            also: Vec::new(),
            thumbs: Thumbs::default(),
            jobs: Vec::new(),
            proxies: Arc::default(),
            hdr_proxies: Default::default(),
            dropping: None,
            width: Rc::default(),
            _subscriptions,
            _poll,
        }
    }

    fn poll(&mut self, cx: &mut Context<Self>) {
        let jobs = self
            .state
            .read(cx)
            .services
            .analysis
            .as_ref()
            .map(|a| a.jobs())
            .unwrap_or_default();
        self.refresh_proxies(cx);
        let proxying = !self.proxies.lock().unwrap().is_empty();
        if jobs != self.jobs || proxying {
            self.jobs = jobs;
            cx.notify();
        }
    }

    /// The item's background work, `None` when idle.
    fn progress(&self, id: MediaId) -> Option<Progress> {
        if let Some(f) = self.proxies.lock().unwrap().get(&id) {
            return Some(Progress::Proxy(*f));
        }
        let job = self.jobs.iter().rev().find(|j| j.media == Some(id))?;
        match &job.state {
            JobState::Queued => Some(Progress::Queued),
            JobState::Running { fraction } => Some(Progress::Analyzing(*fraction)),
            JobState::Done => None,
            JobState::Failed { .. } => Some(Progress::Failed),
        }
    }

    /// The item's "Analyze" entry; `None` for images, which are not
    /// analyzed. Disabled while a task's picked model is missing, unless a
    /// voiceover can do without, or the item is queued or analyzing.
    fn analyze_entry(&self, id: MediaId, cx: &App) -> Option<AnalyzeEntry> {
        let state = self.state.read(cx);
        let item = state.bus.project().media(id)?;
        let analysis = state.services.analysis.as_ref()?;
        if item.kind == MediaKind::Image {
            return None;
        }
        let busy = self
            .jobs
            .iter()
            .rev()
            .find(|j| j.media == Some(id))
            .is_some_and(|j| matches!(j.state, JobState::Queued | JobState::Running { .. }));
        let fp = item.fingerprint.as_ref();
        let script = item.generated.as_deref().and_then(|g| g.script());
        Some(AnalyzeEntry {
            again: fp.and_then(|fp| analysis.analysis(fp)).is_some(),
            enabled: fp.is_some() && (script.is_some() || state.models_ready()) && !busy,
        })
    }

    // ------------------------------------------------------------ actions

    fn analyze(&mut self, id: MediaId, again: bool, cx: &mut Context<Self>) {
        self.state.update(cx, |s, cx| s.analyze(id, again, cx));
        self.poll(cx);
    }

    fn prompt_import(&mut self, cx: &mut Context<Self>) {
        let paths = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: true,
            multiple: true,
            prompt: None,
        });
        cx.spawn(async move |this, cx| {
            if let Ok(Ok(Some(paths))) = paths.await {
                this.update(cx, |this, cx| this.import(paths, this.bin, cx))
                    .ok();
            }
        })
        .detach();
    }

    fn select(&mut self, id: MediaId, open: bool, window: &mut Window, cx: &mut Context<Self>) {
        window.focus(&self.focus, cx);
        let m = window.modifiers();
        if !open && (m.secondary() || m.shift) && self.selected.is_some_and(|s| s != id) {
            match self.also.iter().position(|a| *a == id) {
                Some(i) => {
                    self.also.remove(i);
                }
                None => self.also.push(id),
            }
            cx.notify();
            return;
        }
        self.also.clear();
        self.selected = Some(id);
        if open {
            match self.selected_item(cx) {
                Some(item) if self.state.read(cx).can_listen(&item) => {
                    self.state.update(cx, |s, cx| s.toggle_source(&item, cx));
                }
                _ => self.state.update(cx, |s, cx| s.open_source(id, cx)),
            }
        }
        cx.notify();
    }

    /// Ask, then remove `id` from the project together with its clips.
    fn confirm_remove(&mut self, id: MediaId, window: &mut Window, cx: &mut Context<Self>) {
        let state = self.state.read(cx);
        let Some(item) = state.bus.project().media(id) else {
            return;
        };
        let name = item_name(item);
        let clips = state.clips_using(id).len();
        let (state, panel) = (self.state.clone(), cx.entity().downgrade());
        window.open_confirm(cx, move |dialog, _, _| {
            let (state, panel) = (state.clone(), panel.clone());
            let dialog = dialog
                .title(format!("Remove “{name}” from the project?"))
                .destructive()
                .confirm("Remove", move |_, cx| {
                    state.update(cx, |s, cx| s.remove_media(id, cx));
                    let _ = panel.update(cx, |this, cx| {
                        if this.selected == Some(id) {
                            this.selected = None;
                            cx.notify();
                        }
                    });
                    true
                });
            match clips {
                0 => dialog,
                1 => dialog.description("Its clip is removed from the timeline too."),
                n => {
                    dialog.description(format!("Its {n} clips are removed from the timeline too."))
                }
            }
        });
    }

    fn update_media(&self, item: MediaItem, cx: &mut Context<Self>) {
        self.state.update(cx, |s, cx| {
            s.execute(Command::UpdateMedia { media: item }, cx);
        });
    }

    /// The selected items to sync when `id` is one of them, reference
    /// first, and whether they hold a recorder and a camera.
    fn sync_group(&self, id: MediaId, cx: &App) -> Option<(Vec<MediaId>, bool)> {
        let selected = self.selected?;
        if self.also.is_empty() || (selected != id && !self.also.contains(&id)) {
            return None;
        }
        let project = self.state.read(cx).bus.project();
        let mut all = vec![selected];
        all.extend(&self.also);
        let group = flikk_core::sync::pool_order(project, &all);
        if group.len() < 2 {
            return None;
        }
        let kind = |k| {
            group
                .iter()
                .any(|m| project.media(*m).is_some_and(|i| i.kind == k))
        };
        let recorder = kind(MediaKind::Audio) && kind(MediaKind::Video);
        Some((group, recorder))
    }

    fn selected_item(&self, cx: &App) -> Option<MediaItem> {
        let id = self.selected?;
        self.state.read(cx).bus.project().media(id).cloned()
    }

    fn add_tag(&mut self, tag: String, cx: &mut Context<Self>) {
        let Some(mut item) = self.selected_item(cx) else {
            return;
        };
        if tag.is_empty() || item.tags.iter().any(|t| t.eq_ignore_ascii_case(&tag)) {
            return;
        }
        item.tags.push(tag);
        self.update_media(item, cx);
    }

    fn remove_tag(&mut self, tag: &str, cx: &mut Context<Self>) {
        let Some(mut item) = self.selected_item(cx) else {
            return;
        };
        item.tags.retain(|t| t != tag);
        self.update_media(item, cx);
    }

    fn move_to_bin(&mut self, media: MediaId, bin: Option<BinId>, cx: &mut Context<Self>) {
        let Some(mut item) = self.state.read(cx).bus.project().media(media).cloned() else {
            return;
        };
        if item.bin != bin {
            item.bin = bin;
            self.update_media(item, cx);
        }
    }

    fn bins(&self, cx: &App) -> Vec<Bin> {
        self.state.read(cx).bus.project().bins.clone()
    }

    fn new_bin(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let mut bins = self.bins(cx);
        let n = bins.len() + 1;
        let bin = Bin {
            id: BinId::new(),
            name: format!("Bin {n}"),
            parent: None,
        };
        let id = bin.id;
        bins.push(bin);
        self.state.update(cx, |s, cx| {
            s.execute(Command::SetBins { bins }, cx);
        });
        self.start_rename(id, window, cx);
    }

    fn start_rename(&mut self, id: BinId, window: &mut Window, cx: &mut Context<Self>) {
        let name = self
            .bins(cx)
            .into_iter()
            .find(|b| b.id == id)
            .map(|b| b.name)
            .unwrap_or_default();
        self.renaming = Some(id);
        // Typing replaces the name; an empty entry keeps it.
        self.bin_input.update(cx, |i, cx| {
            i.set_value("", window, cx);
            i.set_placeholder(name, window, cx);
            i.focus(window, cx);
        });
        cx.notify();
    }

    fn finish_rename(&mut self, name: String, cx: &mut Context<Self>) {
        let Some(id) = self.renaming.take() else {
            return;
        };
        if !name.is_empty() {
            let mut bins = self.bins(cx);
            if let Some(b) = bins.iter_mut().find(|b| b.id == id) {
                b.name = name;
                self.state.update(cx, |s, cx| {
                    s.execute(Command::SetBins { bins }, cx);
                });
            }
        }
        cx.notify();
    }

    /// Files from outside moved over the items, or off them.
    fn drag_files(
        &mut self,
        ev: &DragMoveEvent<ExternalPaths>,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let over = ev
            .bounds
            .contains(&ev.event.position)
            .then(|| ev.drag(cx).paths().to_vec());
        if over != self.dropping {
            self.dropping = over;
            cx.notify();
        }
    }

    // ------------------------------------------------------------- render

    fn visible_items(&self, cx: &App) -> Vec<MediaItem> {
        let query = self.search.read(cx).value().trim().to_lowercase();
        let project = self.state.read(cx).bus.project();
        project
            .media
            .iter()
            .filter(|m| self.bin.is_none() || m.bin == self.bin)
            .filter(|m| {
                query.is_empty()
                    || item_name(m).to_lowercase().contains(&query)
                    || m.tags.iter().any(|t| t.to_lowercase().contains(&query))
            })
            .cloned()
            .collect()
    }

    /// The Edit panel header's actions while the pool shows: generate and
    /// import.
    pub fn header_actions(&self, cx: &mut Context<Self>) -> AnyElement {
        let generate = Button::new("generate")
            .ghost()
            .small()
            .icon(IconName::Clapperboard)
            .tooltip("Generate");
        h_flex()
            .gap(px(2.))
            .children(self.generate_menu(generate, cx))
            .child(
                Button::new("import")
                    .ghost()
                    .small()
                    .icon(IconName::Plus)
                    .tooltip("Import")
                    .on_click(cx.listener(|this, _, _, cx| this.prompt_import(cx))),
            )
            .into_any_element()
    }

    /// `button` opening what a provider can make; `None` when none can.
    fn generate_menu(&self, button: Button, cx: &mut Context<Self>) -> Option<AnyElement> {
        let generate = self.can_generate(cx);
        let video = self.video_model(cx);
        let can_voiceover = self.can_voiceover(cx);
        if generate.is_empty() && video.is_none() && !can_voiceover {
            return None;
        }
        let panel = cx.entity();
        let menu = button.dropdown_menu(move |mut menu, _, _| {
            for &kind in &generate {
                let panel = panel.clone();
                menu = menu.item(
                    PopupMenuItem::new(format!("{}…", kind.label()))
                        .icon(kind.icon())
                        .on_click(move |_, window, cx| {
                            panel.update(cx, |this, cx| this.open_generate(kind, window, cx))
                        }),
                );
            }
            if let Some(model) = video.clone() {
                let p = panel.clone();
                menu = menu.item(PopupMenuItem::new("Video…").icon(IconName::Video).on_click(
                    move |_, window, cx| {
                        let model = model.clone();
                        p.update(cx, |this, cx| this.open_video(model, window, cx))
                    },
                ));
            }
            if can_voiceover {
                let p = panel.clone();
                menu = menu.item(
                    PopupMenuItem::new("Voiceover…")
                        .icon(IconName::Mic)
                        .on_click(move |_, window, cx| {
                            p.update(cx, |this, cx| this.open_voiceover(None, window, cx))
                        }),
                );
                let p = panel.clone();
                menu = menu
                    .separator()
                    .item(
                        PopupMenuItem::new("Voices…").on_click(move |_, window, cx| {
                            let state = p.read(cx).state.clone();
                            crate::ui::voices::open(
                                state,
                                crate::ui::voices::Start::Find,
                                None,
                                window,
                                cx,
                            );
                        }),
                    );
            }
            menu
        });
        Some(menu.into_any_element())
    }

    fn search_row(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let toggle = |id: &'static str, icon: IconName, tip: &'static str, layout: Layout| {
            Button::new(id)
                .ghost()
                .icon(icon)
                .tooltip(tip)
                .selected(self.layout == layout)
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.layout = layout;
                    cx.notify();
                }))
        };
        h_flex()
            .flex_none()
            .gap(px(4.))
            .p(px(8.))
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .child(Input::new(&self.search).search().kbd("/")),
            )
            .child(toggle("grid", IconName::LayoutGrid, "Grid", Layout::Grid))
            .child(toggle("list", IconName::List, "List", Layout::List))
    }

    /// All media, then each bin under its parent, then "New bin".
    fn bins_tree(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let project = self.state.read(cx).bus.project();
        let total = project.media.len();
        let mut counts: HashMap<BinId, usize> = HashMap::new();
        for bin in project.media.iter().filter_map(|m| m.bin) {
            *counts.entry(bin).or_default() += 1;
        }
        let bins = project.bins.clone();
        let tree = bin_tree(&bins);
        let mut rows = vec![
            bin_row("bin-all", self.bin.is_none(), 0)
                .child(Icon::new(IconName::FolderOpen).size(px(12.)).color(t::T2))
                .child(div().flex_1().min_w_0().truncate().child("All media"))
                .child(count(total))
                .on_click(cx.listener(|this, _, _, cx| {
                    this.bin = None;
                    cx.notify();
                }))
                .on_drop(cx.listener(|this, drag: &MediaDrag, _, cx| {
                    this.move_to_bin(drag.media, None, cx)
                }))
                .on_drop(cx.listener(|this, paths: &ExternalPaths, _, cx| {
                    this.import(paths.paths().to_vec(), None, cx)
                }))
                .into_any_element(),
        ];
        for (bin, depth) in tree {
            let id = bin.id;
            let selected = self.bin == Some(id);
            let row = bin_row(
                ElementId::Name(format!("bin-{id}").into()),
                selected,
                depth + 1,
            )
            .child(Icon::new(IconName::Folder).size(px(12.)));
            if self.renaming == Some(id) {
                rows.push(
                    row.child(div().flex_1().child(Input::new(&self.bin_input).small()))
                        .into_any_element(),
                );
                continue;
            }
            rows.push(
                row.child(div().flex_1().min_w_0().truncate().child(bin.name.clone()))
                    .child(count(counts.get(&id).copied().unwrap_or(0)))
                    .on_click(cx.listener(move |this, ev: &ClickEvent, window, cx| {
                        if ev.click_count() >= 2 {
                            this.start_rename(id, window, cx);
                        } else {
                            this.bin = Some(id);
                            cx.notify();
                        }
                    }))
                    .on_drop(cx.listener(move |this, drag: &MediaDrag, _, cx| {
                        this.move_to_bin(drag.media, Some(id), cx)
                    }))
                    .on_drop(cx.listener(move |this, paths: &ExternalPaths, _, cx| {
                        this.import(paths.paths().to_vec(), Some(id), cx)
                    }))
                    .into_any_element(),
            );
        }
        rows.push(
            bin_row("new-bin", false, 1)
                .text_color(t::T3)
                .child(Icon::new(IconName::FolderPlus).size(px(12.)))
                .child("New bin")
                .on_click(cx.listener(|this, _, window, cx| this.new_bin(window, cx)))
                .into_any_element(),
        );
        div()
            .id("bins")
            .flex_none()
            .max_h(px(200.))
            .px(px(4.))
            .pb(px(6.))
            .overflow_y_scrollbar()
            .child(v_flex().children(rows))
    }

    /// What a tile or row shows of `item`.
    fn look(&mut self, item: &MediaItem, cx: &mut Context<Self>) -> Look {
        let thumb = self.thumbs.get(item, &self.state, cx);
        let state = self.state.read(cx);
        let listening = state.source.as_ref().filter(|p| p.is(item));
        let used = state.clips_using(item.id).len();
        Look {
            thumb,
            name: item_name(item).into(),
            meta: meta(item, used),
            listenable: state.can_listen(item),
            listening: listening.map(|p| p.fraction()),
            progress: self.progress(item.id),
            selected: self.selected == Some(item.id) || self.also.contains(&item.id),
            offline: state.offline.contains(&item.id),
        }
    }

    /// The tile's or row's "⋯", shown on hover.
    fn more_button(&self, id: MediaId, group: SharedString, cx: &mut Context<Self>) -> Div {
        let panel = cx.entity();
        div()
            .opacity(0.)
            .group_hover(group, |s| s.opacity(1.))
            .child(
                Button::new(ElementId::Name(format!("media-menu-{id}").into()))
                    .ghost()
                    .xsmall()
                    .icon(IconName::Ellipsis)
                    .dropdown_menu(move |menu, _, cx| item_menu(menu, &panel, id, cx)),
            )
    }

    fn tile(&mut self, item: &MediaItem, cx: &mut Context<Self>) -> AnyElement {
        let look = self.look(item, cx);
        let id = item.id;
        let group = SharedString::from(format!("media-{id}"));
        let multi =
            (self.selected == Some(id) && !self.also.is_empty()).then(|| self.also.len() + 1);
        let mut thumb = thumb_box(&look, item)
            .when(look.selected, |d| d.shadow(ring()))
            .children(look.listenable.then(|| {
                div().absolute().top(px(4.)).left(px(4.)).child(listen_dot(
                    format!("listen-{id}"),
                    &self.state,
                    item,
                    px(18.),
                    cx,
                ))
            }))
            .children(multi.map(|n| {
                thumb_badge()
                    .bg(t::AC)
                    .text_color(t::ON_AC)
                    .child(Icon::new(IconName::Check).size(px(9.)))
                    .child(n.to_string())
            }))
            .children(item.info.as_ref().map(|i| duration_chip(i.duration)))
            .child(
                self.more_button(id, group.clone(), cx)
                    .absolute()
                    .top(px(3.))
                    .right(px(3.)),
            );
        if multi.is_none() && !look.listenable {
            thumb = thumb.children(corner_badge(item, look.progress));
        }
        let name_color = if look.offline { t::WARN } else { t::T1 };
        let meta = self.meta_line(&look, id);
        let tile = self
            .item_frame(item, &group, cx)
            .flex()
            .flex_col()
            .min_w_0()
            .text_size(px(11.))
            .child(thumb)
            .child(
                div()
                    .mt(px(4.))
                    .truncate()
                    .text_color(name_color)
                    .child(look.name.clone()),
            )
            .child(meta);
        self.with_menu(tile, id, cx)
    }

    fn row(&mut self, item: &MediaItem, wide: bool, cx: &mut Context<Self>) -> AnyElement {
        let look = self.look(item, cx);
        let id = item.id;
        let group = SharedString::from(format!("media-{id}"));
        let mini = div()
            .relative()
            .flex()
            .flex_none()
            .items_center()
            .justify_center()
            .w(px(36.))
            .h(px(20.))
            .rounded(px(3.))
            .overflow_hidden()
            .bg(thumb_bg(item))
            .map(|d| match (&look.thumb, item.kind) {
                _ if look.offline => {
                    d.child(Icon::new(IconName::Unlink).size(px(11.)).color(t::WARN))
                }
                (Some(image), _) => {
                    d.child(img(image.clone()).size_full().object_fit(ObjectFit::Cover))
                }
                (None, MediaKind::Audio) if look.listenable => d.child(listen_dot(
                    format!("listen-{id}"),
                    &self.state,
                    item,
                    px(16.),
                    cx,
                )),
                (None, MediaKind::Audio) => {
                    d.child(Icon::new(IconName::AudioLines).size(px(11.)).color(t::A))
                }
                (None, MediaKind::Image) => {
                    d.child(Icon::new(IconName::Image).size(px(11.)).color(t::T3))
                }
                (None, MediaKind::Video) => d,
            });
        let bar = look
            .listening
            .map(|f| (f, t::T1))
            .or(look.progress.and_then(Progress::bar));
        let name_color = if look.offline { t::WARN } else { t::T1 };
        let duration = item
            .info
            .as_ref()
            .map_or("—".to_owned(), |i| clock(i.duration));
        let selected = look.selected;
        let more = self.more_button(id, group.clone(), cx);
        let bin = self.bin_name(item.bin, cx);
        let row = self
            .item_frame(item, &group, cx)
            .h(px(30.))
            .flex()
            .items_center()
            .gap(px(10.))
            .px(px(8.))
            .rounded(t::RADIUS)
            .text_size(px(12.))
            .when(selected, |d| {
                d.bg(t::alpha(t::AC, 0.1))
                    .shadow(inset_ring(t::alpha(t::AC, 0.4)))
            })
            .when(!selected, |d| d.hover(|s| s.bg(t::HV)))
            .child(mini)
            .child(
                h_flex()
                    .flex_1()
                    .min_w_0()
                    .gap(px(8.))
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_color(name_color)
                            .child(look.name.clone()),
                    )
                    .children(bar.map(|(f, color)| bar3(f, color).w(px(80.)).flex_none())),
            )
            .child(column(duration, 56.).font_family(t::mono()))
            .when(wide, |d| {
                let format = if look.offline {
                    column("Offline", 120.).text_color(t::WARN)
                } else {
                    column(format_of(item), 120.)
                };
                d.child(format).child(column(bin, 90.))
            })
            .child(more);
        self.with_menu(row, id, cx)
    }

    /// What tiles and rows share: selecting, opening, dragging and the
    /// right-click menu.
    fn item_frame(
        &self,
        item: &MediaItem,
        group: &SharedString,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let id = item.id;
        let drag = MediaDrag {
            media: id,
            name: item_name(item).into(),
        };
        div()
            .id(ElementId::Name(group.clone()))
            .group(group.clone())
            .cursor_pointer()
            .on_click(cx.listener(move |this, ev: &ClickEvent, window, cx| {
                this.select(id, ev.click_count() >= 2, window, cx)
            }))
            .on_drag(drag, |drag, _, _, cx| cx.new(|_| drag.clone()))
    }

    /// The item's menu on a right click.
    fn with_menu(&self, el: Stateful<Div>, id: MediaId, cx: &mut Context<Self>) -> AnyElement {
        let panel = cx.entity();
        el.context_menu(move |menu, _, cx| item_menu(menu, &panel, id, cx))
            .into_any_element()
    }

    /// The tile's second line: the item's format, or what is happening to
    /// it.
    fn meta_line(&self, look: &Look, id: MediaId) -> Stateful<Div> {
        let line = div()
            .id(ElementId::Name(format!("meta-{id}").into()))
            .text_size(px(10.))
            .text_color(t::T3)
            .truncate();
        if look.offline {
            let state = self.state.clone();
            return line.child(
                h_flex().gap(px(3.)).child("Offline ·").child(
                    div()
                        .id(ElementId::Name(format!("relink-{id}").into()))
                        .text_color(t::T2)
                        .hover(|s| s.text_color(t::T1))
                        .child("Relink")
                        .on_click(move |_, _, cx| {
                            cx.stop_propagation();
                            crate::relink::relink_item(&state, id, cx)
                        }),
                ),
            );
        }
        match look.progress {
            Some(Progress::Failed) => line.text_color(t::ERR).child("Analysis failed"),
            Some(Progress::Queued) => line.child("Queued for analysis"),
            Some(Progress::Analyzing(f)) => line.child(format!("Analyzing · {:.0}%", f * 100.)),
            Some(Progress::Proxy(_)) => line.child(format!("{} · proxy building", look.meta)),
            None => line.child(look.meta.clone()),
        }
    }

    fn bin_name(&self, bin: Option<BinId>, cx: &App) -> String {
        bin.and_then(|id| {
            let bins = &self.state.read(cx).bus.project().bins;
            bins.iter().find(|b| b.id == id).map(|b| b.name.clone())
        })
        .unwrap_or_default()
    }

    /// The list's column names, when it is wide enough to have columns.
    fn list_header(&self) -> impl IntoElement {
        h_flex()
            .h(px(24.))
            .gap(px(10.))
            .px(px(8.))
            .text_size(px(10.))
            .text_color(t::T3)
            .child(div().w(px(36.)).flex_none())
            .child(div().flex_1().child("Name"))
            .child(column("Duration", 56.))
            .child(column("Format", 120.))
            .child(column("Bin", 90.))
            .child(div().w(px(20.)).flex_none())
    }

    /// Play and seek for a sound.
    fn listen_bar(&self, item: &MediaItem, cx: &App) -> Option<AnyElement> {
        let state = self.state.read(cx);
        if !state.can_listen(item) {
            return None;
        }
        let source = state.source.as_ref().filter(|p| p.is(item));
        let fraction = source.map_or(0., |p| p.fraction());
        let at = source.map_or(Time::ZERO, |p| p.position());
        let (seeker, sound) = (self.state.clone(), item.clone());
        let bar = seek_bar(
            fraction,
            move |f, cx| seeker.update(cx, |s, cx| s.seek_source(&sound, f, cx)),
            cx,
        );
        Some(
            h_flex()
                .gap(px(8.))
                .child(listen_button("listen-selected", &self.state, item, cx))
                .child(bar)
                .child(
                    div()
                        .font_family(t::mono())
                        .text_size(px(10.))
                        .text_color(t::T3)
                        .child(clock(at)),
                )
                .into_any_element(),
        )
    }

    fn details(&self, item: &MediaItem, cx: &mut Context<Self>) -> AnyElement {
        let mut lines: Vec<SharedString> = Vec::new();
        if let Some(info) = &item.info {
            let mut head = vec![clock(info.duration)];
            if let Some(v) = &info.video {
                head.push(format!("{}×{}", v.width, v.height));
                head.push(format!("{:.2} fps", v.rate.fps()).replace(".00", ""));
                head.push(v.codec.clone());
                head.extend(v.hdr.as_ref().map(|h| h.describe()));
            }
            if !info.container.is_empty() {
                head.push(info.container.clone());
            }
            lines.push(head.join(" · ").into());
            for a in &info.audio {
                let mut parts = vec![format!("A{}", a.index)];
                parts.extend(a.language.clone());
                parts.push(format!("{} ch", a.channels));
                parts.push(format!("{} kHz", a.sample_rate / 1000));
                parts.push(a.codec.clone());
                lines.push(parts.join(" · ").into());
            }
        }
        if let Some(fp) = &item.fingerprint {
            lines.push(fp.0.chars().take(16).collect::<String>().into());
        }
        let tags = item.tags.clone();
        let id = item.id;
        v_flex()
            .flex_none()
            .gap(px(6.))
            .px(px(10.))
            .py(px(8.))
            .border_t_1()
            .border_color(t::LN)
            .child(
                h_flex()
                    .gap(px(4.))
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .font_weight(FontWeight::MEDIUM)
                            .truncate()
                            .child(item_name(item)),
                    )
                    .child(
                        Button::new("remove-media")
                            .ghost()
                            .xsmall()
                            .icon(IconName::Trash)
                            .tooltip("Remove from project")
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.confirm_remove(id, window, cx)
                            })),
                    ),
            )
            .children(self.listen_bar(item, cx))
            .child(v_flex().gap(px(2.)).children(lines.into_iter().map(|l| {
                div()
                    .text_size(px(11.))
                    .text_color(t::T3)
                    .truncate()
                    .child(l)
            })))
            .child(
                h_flex()
                    .gap(px(4.))
                    .flex_wrap()
                    .children(tags.into_iter().enumerate().map(|(i, tag)| {
                        let untag = tag.clone();
                        h_flex()
                            .id(("tag", i))
                            .gap(px(2.))
                            .h(px(20.))
                            .pl(px(6.))
                            .pr(px(2.))
                            .rounded(t::RADIUS_SM)
                            .border_1()
                            .border_color(t::LN)
                            .bg(t::R1)
                            .text_size(px(11.))
                            .child(tag)
                            .child(
                                div()
                                    .id(("untag", i))
                                    .cursor_pointer()
                                    .text_color(t::T3)
                                    .hover(|s| s.text_color(t::T1))
                                    .child(Icon::new(IconName::X).size(px(10.)))
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.remove_tag(&untag, cx)
                                    })),
                            )
                    }))
                    .child(div().w(px(96.)).child(Input::new(&self.tag_input).small())),
            )
            .into_any_element()
    }

    /// Before the first import: a drop zone with Import and Generate.
    fn empty(&self, cx: &mut Context<Self>) -> AnyElement {
        let generate = Button::new("empty-generate")
            .ghost()
            .icon(IconName::Clapperboard)
            .label("Generate");
        EmptyState::new(IconName::Film, "No media yet")
            .hint("Drop files or folders here")
            .drop_zone()
            .child(
                Button::new("empty-import")
                    .icon(IconName::Download)
                    .label("Import")
                    .on_click(cx.listener(|this, _, _, cx| this.prompt_import(cx))),
            )
            .children(self.generate_menu(generate, cx))
            .into_any_element()
    }

    /// Over the items while files from outside are dragged there.
    fn drop_overlay(&self, paths: &[PathBuf], cx: &App) -> Div {
        let noun = match (paths.len(), paths.iter().any(|p| p.is_dir())) {
            (1, false) => "file",
            (_, false) => "files",
            (1, true) => "folder",
            (_, true) => "items",
        };
        let title = match self.bin {
            Some(_) => format!(
                "Import {} {noun} to {}",
                paths.len(),
                self.bin_name(self.bin, cx)
            ),
            None => format!("Import {} {noun}", paths.len()),
        };
        let mut names: Vec<String> = paths.iter().take(2).map(|p| file_name(p)).collect();
        if paths.len() > 2 {
            names.push(format!("+{}", paths.len() - 2));
        }
        v_flex()
            .absolute()
            .inset(px(6.))
            .items_center()
            .justify_center()
            .gap(px(6.))
            .rounded(px(6.))
            .border_1()
            .border_dashed()
            .border_color(t::AC)
            .bg(t::alpha(t::AC, 0.08))
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_center()
                    .size(px(30.))
                    .rounded(px(7.))
                    .bg(t::AC_WASH)
                    .child(Icon::new(IconName::Download).size(px(16.)).color(t::AC)),
            )
            .child(div().font_weight(FontWeight::MEDIUM).child(title))
            .child(
                div()
                    .px(px(12.))
                    .max_w_full()
                    .truncate()
                    .font_family(t::mono())
                    .text_size(px(10.))
                    .text_color(t::T2)
                    .child(names.join(" · ")),
            )
    }
}

impl Render for MediaPoolPanel {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if self.dropping.is_some() && !cx.has_active_drag() {
            self.dropping = None;
        }
        let root = v_flex()
            .id("media-pool")
            .size_full()
            .text_size(px(12.))
            .text_color(t::T1)
            .track_focus(&self.focus)
            .key_context("MediaPool")
            .on_action(cx.listener(|this, _: &RemoveSelected, window, cx| {
                if let Some(id) = this.selected {
                    this.confirm_remove(id, window, cx);
                }
            }))
            .on_action(cx.listener(|this, _: &ListenToSelected, _, cx| {
                if let Some(item) = this.selected_item(cx)
                    && this.state.read(cx).can_listen(&item)
                {
                    this.state.update(cx, |s, cx| s.toggle_source(&item, cx));
                }
            }))
            .on_action(cx.listener(|this, _: &FocusSearch, window, cx| {
                this.search.update(cx, |s, cx| s.focus(window, cx));
            }))
            .on_drop(cx.listener(|this, paths: &ExternalPaths, _, cx| {
                this.dropping = None;
                this.import(paths.paths().to_vec(), this.bin, cx)
            }));
        let project = self.state.read(cx).bus.project();
        let generating = self.state.read(cx).generating.clone();
        if project.media.is_empty() && project.bins.is_empty() && generating.is_empty() {
            return root.child(self.empty(cx));
        }

        let items = self.visible_items(cx);
        let width = self.width.get().as_f32();
        let wide = width >= WIDE_LIST;
        let content: AnyElement = if items.is_empty() && generating.is_empty() {
            let searching = !self.search.read(cx).value().trim().is_empty();
            match searching {
                true => EmptyState::new(IconName::Search, "No matches").compact(),
                false => EmptyState::new(IconName::Inbox, "Nothing in this bin").compact(),
            }
            .into_any_element()
        } else {
            match self.layout {
                Layout::Grid => {
                    let cols = if width > 0. {
                        ((width - 16. + 8.) / (TILE + 8.)).floor().max(1.) as u16
                    } else {
                        2
                    };
                    let mut tiles: Vec<AnyElement> = generating
                        .iter()
                        .map(|g| self.generation_tile(g, cx))
                        .collect();
                    tiles.extend(items.iter().map(|m| self.tile(m, cx)));
                    div()
                        .grid()
                        .grid_cols(cols)
                        .gap_x(px(8.))
                        .gap_y(px(10.))
                        .px(px(8.))
                        .py(px(10.))
                        .children(tiles)
                        .into_any_element()
                }
                Layout::List => {
                    let mut rows: Vec<AnyElement> = generating
                        .iter()
                        .map(|g| self.generation_row(g, cx))
                        .collect();
                    rows.extend(items.iter().map(|m| self.row(m, wide, cx)));
                    v_flex()
                        .p(px(4.))
                        .when(wide, |d| d.child(self.list_header()))
                        .children(rows)
                        .into_any_element()
                }
            }
        };
        let measured = self.width.clone();
        let dropping = self.dropping.clone();
        let selected = self.selected_item(cx);
        root.child(self.search_row(cx))
            .child(self.bins_tree(cx))
            .child(div().flex_none().h(px(1.)).bg(t::LN))
            .child(
                div()
                    .relative()
                    .flex_1()
                    .min_h_0()
                    .on_drag_move(cx.listener(Self::drag_files))
                    .child(
                        canvas(move |b, _, _| measured.set(b.size.width), |_, _, _, _| {})
                            .absolute()
                            .size_full(),
                    )
                    .child(
                        div()
                            .id("media-items")
                            .size_full()
                            .overflow_y_scrollbar()
                            .child(content),
                    )
                    .children(dropping.map(|paths| self.drop_overlay(&paths, cx))),
            )
            .children(selected.map(|item| self.details(&item, cx)))
    }
}

/// What a tile or row shows of an item, read once per frame.
struct Look {
    thumb: Option<Arc<Image>>,
    name: SharedString,
    meta: String,
    listenable: bool,
    /// How far the item plays, while it is the source.
    listening: Option<f32>,
    progress: Option<Progress>,
    selected: bool,
    offline: bool,
}

/// The "Analyze" entry of an item's menu.
#[derive(Clone, Copy)]
struct AnalyzeEntry {
    /// The item has results, which analyzing replaces.
    again: bool,
    enabled: bool,
}

/// The menu of item `id`, from its "⋯" button or a right click; built as
/// it opens, so what it offers is current.
fn item_menu(menu: PopupMenu, panel: &Entity<MediaPoolPanel>, id: MediaId, cx: &App) -> PopupMenu {
    let mut menu = menu;
    let state = panel.read(cx).state.clone();
    if state.read(cx).offline.contains(&id) {
        menu = menu
            .item(
                PopupMenuItem::new("Relink…")
                    .icon(IconName::Unlink)
                    .on_click(move |_, _, cx| crate::relink::relink_item(&state, id, cx)),
            )
            .separator();
    }
    if let Some(entry) = panel.read(cx).analyze_entry(id, cx) {
        let panel = panel.clone();
        let label = if entry.again {
            "Analyze again"
        } else {
            "Analyze"
        };
        menu = menu.item(PopupMenuItem::new(label).disabled(!entry.enabled).on_click(
            move |_, _, cx| panel.update(cx, |this, cx| this.analyze(id, entry.again, cx)),
        ));
    }
    let (open, remove) = (panel.clone(), panel.clone());
    let state = panel.read(cx).state.clone();
    let sound = state.read(cx).bus.project().media(id);
    let sound = sound
        .filter(|item| state.read(cx).can_listen(item))
        .is_some();
    let open_label = match sound {
        true if listening_to(&state, id, cx) => "Pause",
        true => "Play",
        false => "Open in viewer",
    };
    let menu = menu.item(
        PopupMenuItem::new(open_label).on_click(move |_, window, cx| {
            open.update(cx, |this, cx| this.select(id, true, window, cx))
        }),
    );
    let menu = if shared::can_save_sound(state.read(cx), id) {
        menu.item(
            PopupMenuItem::new("Add to Library")
                .on_click(move |_, _, cx| state.update(cx, |s, cx| shared::save_sound(s, id, cx))),
        )
    } else {
        menu
    };
    let menu = match voiceover_take(panel, id, cx) {
        Some(take) => {
            let p = panel.clone();
            let state = panel.read(cx).state.clone();
            let saved = voice_saved(&state, &take, cx);
            let menu = menu.item(PopupMenuItem::new("Regenerate…").on_click(
                move |_, window, cx| {
                    let take = Some(take.clone());
                    p.update(cx, |this, cx| this.open_voiceover(take, window, cx))
                },
            ));
            if saved {
                menu
            } else {
                let s = state.clone();
                menu.item(
                    PopupMenuItem::new("Save Voice to Library")
                        .on_click(move |_, _, cx| s.update(cx, |s, cx| save_voice(s, id, cx))),
                )
            }
        }
        None => menu,
    };
    let menu = match panel.read(cx).sync_group(id, cx) {
        Some((group, recorder)) => {
            let item = |label: &'static str, mute: bool| {
                let state = panel.read(cx).state.clone();
                let group = group.clone();
                PopupMenuItem::new(label).on_click(move |_, _, cx| {
                    let group = group.clone();
                    state.update(cx, |s, cx| s.sync_media(group, mute, cx))
                })
            };
            let menu = menu.item(item("Sync", false));
            if recorder {
                menu.item(item("Sync, Recorder Sound", true))
            } else {
                menu
            }
        }
        None => menu,
    };
    menu.separator().item(
        PopupMenuItem::new("Remove from project")
            .icon(IconName::Trash)
            .destructive()
            .on_click(move |_, window, cx| {
                remove.update(cx, |this, cx| this.confirm_remove(id, window, cx))
            }),
    )
}

/// The voiceover `id` is, when a provider can make it again.
fn voiceover_take(
    panel: &Entity<MediaPoolPanel>,
    id: MediaId,
    cx: &App,
) -> Option<voiceover::Take> {
    let panel = panel.read(cx);
    let state = panel.state.read(cx);
    let generated = state.bus.project().media(id)?.generated.as_deref()?;
    let reading = generated.reading.clone()?;
    panel.can_voiceover(cx).then(|| voiceover::Take {
        script: generated.prompt.clone(),
        reading,
    })
}

/// Whether the voice that read `take` is in the library.
fn voice_saved(state: &Entity<EditorState>, take: &voiceover::Take, cx: &App) -> bool {
    let state = state.read(cx);
    let provider = state.voice_provider().unwrap_or_default();
    state
        .library
        .voice_of(&provider, &take.reading.voice)
        .is_some()
}

/// Keep the voice that read voiceover `id` in the library, with the
/// voiceover as its sample.
fn save_voice(s: &mut EditorState, id: MediaId, cx: &mut Context<EditorState>) {
    let Some(item) = s.bus.project().media(id).cloned() else {
        return;
    };
    let Some(reading) = item.generated.as_deref().and_then(|g| g.reading.clone()) else {
        return;
    };
    let known = s
        .account_voices
        .voices
        .iter()
        .flatten()
        .find(|v| v.id == reading.voice)
        .cloned();
    let voice = known.unwrap_or_else(|| flikk_core::cloud::Voice {
        id: reading.voice.clone(),
        name: reading.voice_name.clone(),
        ..Default::default()
    });
    s.keep_voice(
        &voice,
        flikk_core::cloud::VoiceOrigin::Account,
        Some(&item),
        cx,
    );
    s.keep_reading(&reading, cx);
}

/// Whether pool item `id` is playing.
fn listening_to(state: &Entity<EditorState>, id: MediaId, cx: &App) -> bool {
    let state = state.read(cx);
    let item = state.bus.project().media(id);
    let preview = state.source.as_ref();
    item.zip(preview)
        .is_some_and(|(item, p)| p.is(item) && p.is_playing())
}

/// `bins` in tree order, each with how deep it sits.
fn bin_tree(bins: &[Bin]) -> Vec<(&Bin, usize)> {
    fn under<'a>(
        bins: &'a [Bin],
        parent: Option<BinId>,
        depth: usize,
        out: &mut Vec<(&'a Bin, usize)>,
    ) {
        for bin in bins.iter().filter(|b| b.parent == parent) {
            out.push((bin, depth));
            under(bins, Some(bin.id), depth + 1, out);
        }
    }
    let mut out = Vec::new();
    under(bins, None, 0, &mut out);
    // A bin whose parent is gone sits at the top.
    for bin in bins {
        if !out.iter().any(|(b, _)| b.id == bin.id) {
            out.push((bin, 0));
            under(bins, Some(bin.id), 1, &mut out);
        }
    }
    out
}

/// A row of the bins tree, indented `depth` levels.
fn bin_row(id: impl Into<ElementId>, selected: bool, depth: usize) -> Stateful<Div> {
    h_flex()
        .id(id)
        .h(px(24.))
        .gap(px(6.))
        .pl(px(6. + 16. * depth as f32))
        .pr(px(6.))
        .rounded(t::RADIUS_SM)
        .cursor_pointer()
        .text_color(if selected { t::T1 } else { t::T2 })
        .when(selected, |d| d.bg(t::HV))
        .when(!selected, |d| d.hover(|s| s.bg(t::alpha(t::HV, 0.6))))
        .drag_over::<MediaDrag>(|s, _, _, _| s.bg(t::AC_WASH))
        .drag_over::<ExternalPaths>(|s, _, _, _| s.bg(t::AC_WASH))
}

/// A mono item count at the end of a bins row.
fn count(n: usize) -> impl IntoElement {
    div()
        .flex_none()
        .font_family(t::mono())
        .text_size(px(10.))
        .text_color(t::T3)
        .child(n.to_string())
}

/// A fixed-width list column.
fn column(text: impl Into<SharedString>, width: f32) -> Div {
    div()
        .w(px(width))
        .flex_none()
        .truncate()
        .text_size(px(11.))
        .text_color(t::T2)
        .child(text.into())
}

/// The 16:9 picture of a tile: the frame, or the kind's mark, the offline
/// veil and the progress along the bottom.
fn thumb_box(look: &Look, item: &MediaItem) -> Div {
    let bar = look
        .listening
        .map(|f| (f, t::T1))
        .or(look.progress.and_then(Progress::bar));
    div()
        .relative()
        .w_full()
        .aspect_ratio(16. / 9.)
        .rounded(t::RADIUS_SM)
        .overflow_hidden()
        .bg(thumb_bg(item))
        .map(|d| match (&look.thumb, item.kind) {
            (Some(image), _) => {
                d.child(img(image.clone()).size_full().object_fit(ObjectFit::Cover))
            }
            (None, MediaKind::Audio) => d.child(
                div()
                    .absolute()
                    .inset_0()
                    .flex()
                    .items_center()
                    .justify_center()
                    .child(Icon::new(IconName::AudioLines).size(px(22.)).color(t::A)),
            ),
            (None, MediaKind::Image) => d.child(
                div()
                    .absolute()
                    .inset_0()
                    .flex()
                    .items_center()
                    .justify_center()
                    .child(Icon::new(IconName::Image).size(px(16.)).color(t::T3)),
            ),
            (None, MediaKind::Video) => d,
        })
        .when(look.offline, |d| {
            d.child(
                div()
                    .absolute()
                    .inset_0()
                    .flex()
                    .items_center()
                    .justify_center()
                    .bg(t::alpha(t::G, 0.7))
                    .child(Icon::new(IconName::Unlink).size(px(14.)).color(t::WARN)),
            )
        })
        .children(bar.map(|(f, color)| {
            div()
                .absolute()
                .left_0()
                .bottom_0()
                .h(px(2.))
                .w(relative(f.clamp(0., 1.)))
                .bg(color)
        }))
}

/// The ground of a thumbnail before (or without) its frame.
fn thumb_bg(item: &MediaItem) -> Rgba {
    match item.kind {
        MediaKind::Audio => t::alpha(t::A, 0.1),
        _ => t::R1,
    }
}

/// A small label in a thumbnail's top-left corner.
fn thumb_badge() -> Div {
    h_flex()
        .absolute()
        .top(px(3.))
        .left(px(3.))
        .gap(px(3.))
        .h(px(14.))
        .px(px(4.))
        .rounded(px(3.))
        .bg(t::alpha(t::G, 0.67))
        .text_size(px(9.))
        .line_height(px(14.))
        .text_color(t::T1)
}

/// The badge a tile wears in its corner: what is happening to it, else
/// who read it or HDR.
fn corner_badge(item: &MediaItem, progress: Option<Progress>) -> Option<Div> {
    match progress {
        Some(Progress::Failed) => {
            return Some(
                thumb_badge()
                    .text_color(t::ERR)
                    .child(Icon::new(IconName::CircleAlert).size(px(9.)))
                    .child("Failed"),
            );
        }
        Some(Progress::Analyzing(_)) => {
            return Some(
                thumb_badge()
                    .child(Spinner::new().size(px(8.)))
                    .child("Analyzing"),
            );
        }
        Some(Progress::Proxy(f)) => {
            return Some(
                thumb_badge()
                    .font_family(t::mono())
                    .text_color(t::T2)
                    .child(format!("Proxy {:.0}%", f * 100.)),
            );
        }
        Some(Progress::Queued) | None => {}
    }
    let reading = item.generated.as_deref().and_then(|g| g.reading.as_ref());
    if let Some(reading) = reading {
        return Some(
            thumb_badge()
                .child(Icon::new(IconName::Mic).size(px(9.)))
                .child(reading.voice_name.clone()),
        );
    }
    flikk_core::hdr::hdr_of(item)?;
    Some(thumb_badge().font_weight(FontWeight::SEMIBOLD).child("HDR"))
}

/// The duration over a thumbnail's bottom-right corner.
fn duration_chip(duration: Time) -> impl IntoElement {
    div()
        .absolute()
        .right(px(3.))
        .bottom(px(3.))
        .px(px(3.))
        .rounded(px(2.))
        .bg(t::alpha(t::G, 0.67))
        .font_family(t::mono())
        .font_weight(FontWeight::MEDIUM)
        .text_size(px(9.))
        .text_color(t::T1)
        .child(clock(duration))
}

/// A 3 px bar at `fraction` in `color`.
fn bar3(fraction: f32, color: Rgba) -> Div {
    div()
        .h(px(3.))
        .rounded_full()
        .bg(t::alpha(t::T1, 0.08))
        .child(
            div()
                .h_full()
                .rounded_full()
                .w(relative(fraction.clamp(0., 1.)))
                .bg(color),
        )
}

/// Selection: a 1.5 px accent ring around a thumbnail.
fn ring() -> Vec<BoxShadow> {
    vec![BoxShadow {
        color: t::AC.into(),
        offset: point(px(0.), px(0.)),
        blur_radius: px(0.),
        spread_radius: px(1.5),
        inset: false,
    }]
}

/// A 1 px ring inside a selected row.
fn inset_ring(color: Rgba) -> Vec<BoxShadow> {
    vec![BoxShadow {
        color: color.into(),
        offset: point(px(0.), px(0.)),
        blur_radius: px(0.),
        spread_radius: px(1.),
        inset: true,
    }]
}

/// "4K · 25p · used ×3", "WAV · 48 kHz", "Voiceover · 112 words".
fn meta(item: &MediaItem, used: usize) -> String {
    let mut parts: Vec<String> = Vec::new();
    let ext = item
        .path
        .extension()
        .map(|e| e.to_string_lossy().to_uppercase());
    let script = item
        .generated
        .as_deref()
        .filter(|g| g.reading.is_some())
        .map(|g| g.prompt.split_whitespace().count());
    if let Some(words) = script {
        parts.push("Voiceover".into());
        parts.push(format!("{words} words"));
    } else if let Some(v) = item.info.as_ref().and_then(|i| i.video.as_ref()) {
        if item.kind == MediaKind::Image {
            parts.extend(ext);
            parts.push(format!("{}×{}", v.width, v.height));
        } else {
            parts.push(resolution(v.width, v.height));
            parts.push(format!("{}p", trim_rate(v.rate.fps())));
        }
    } else {
        parts.extend(ext);
        if let Some(a) = item.info.as_ref().and_then(|i| i.audio.first()) {
            parts.push(format!("{} kHz", a.sample_rate / 1000));
        }
    }
    if used > 0 {
        parts.push(format!("used ×{used}"));
    }
    parts.join(" · ")
}

/// The list's format column: picture size and rate, or the first sound.
fn format_of(item: &MediaItem) -> String {
    let Some(info) = &item.info else {
        return String::new();
    };
    if let Some(v) = &info.video {
        if item.kind == MediaKind::Image {
            return format!("{}×{}", v.width, v.height);
        }
        return format!("{}×{} · {} fps", v.width, v.height, trim_rate(v.rate.fps()));
    }
    info.audio
        .first()
        .map(|a| {
            format!(
                "A{} · {} ch · {} kHz",
                a.index,
                a.channels,
                a.sample_rate / 1000
            )
        })
        .unwrap_or_default()
}

/// "4K", "6K", or the height for HD and smaller.
fn resolution(width: u32, height: u32) -> String {
    match width {
        w if w >= 7680 => "8K".into(),
        w if w >= 6144 => "6K".into(),
        w if w >= 5120 => "5K".into(),
        w if w >= 3840 => "4K".into(),
        _ => height.to_string(),
    }
}

/// "25", "29.97".
fn trim_rate(fps: f64) -> String {
    let s = format!("{fps:.2}");
    s.trim_end_matches('0').trim_end_matches('.').to_owned()
}

fn file_name(path: &std::path::Path) -> String {
    path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.display().to_string())
}

/// A bar at `fraction`; a click on it calls `seek` with where, 0..1.
pub(crate) fn seek_bar(
    fraction: f32,
    seek: impl Fn(f32, &mut App) + 'static,
    _: &App,
) -> impl IntoElement {
    let bounds = Rc::new(Cell::new(Bounds::<Pixels>::default()));
    let seen = bounds.clone();
    div()
        .relative()
        .flex_1()
        .min_w_0()
        .h(px(14.))
        .flex()
        .items_center()
        .cursor_pointer()
        .on_mouse_down(MouseButton::Left, move |ev, _, cx| {
            let b = bounds.get();
            seek((ev.position.x - b.left()) / b.size.width, cx);
        })
        .child(
            canvas(move |b, _, _| seen.set(b), |_, _, _, _| {})
                .absolute()
                .size_full(),
        )
        .child(bar3(fraction, t::T1).w_full())
}

/// Play or pause `item`, in the pool, the library or a dialog.
pub(crate) fn listen_button(
    id: impl Into<ElementId>,
    state: &Entity<EditorState>,
    item: &MediaItem,
    cx: &App,
) -> Stateful<Div> {
    listen_dot(id, state, item, px(22.), cx)
}

/// A round play button `size` across; white while `item` plays.
pub(crate) fn listen_dot(
    id: impl Into<ElementId>,
    state: &Entity<EditorState>,
    item: &MediaItem,
    size: Pixels,
    cx: &App,
) -> Stateful<Div> {
    let preview = state.read(cx).source.as_ref();
    let playing = preview.is_some_and(|p| p.is(item) && p.is_playing());
    let (state, item) = (state.clone(), item.clone());
    play_dot(id, playing, size)
        .tooltip(Tooltip::text(if playing { "Pause" } else { "Play" }))
        .on_click(move |_, _, cx| {
            cx.stop_propagation();
            state.update(cx, |s, cx| s.toggle_source(&item, cx));
        })
}

/// The round play button's look, without what it plays.
pub(crate) fn play_dot(id: impl Into<ElementId>, playing: bool, size: Pixels) -> Stateful<Div> {
    div()
        .id(id)
        .flex()
        .flex_none()
        .items_center()
        .justify_center()
        .size(size)
        .rounded_full()
        .cursor_pointer()
        .when(playing, |d| d.bg(t::T1).text_color(t::G))
        .when(!playing, |d| {
            d.bg(t::HV).text_color(t::T1).hover(|s| s.bg(t::PS))
        })
        .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
        .child(
            Icon::new(if playing {
                IconName::Pause
            } else {
                IconName::Play
            })
            .size(size * 0.45),
        )
}

#[derive(Clone, Copy)]
enum Progress {
    Proxy(f32),
    Queued,
    Analyzing(f32),
    Failed,
}

impl Progress {
    /// The bar along the thumbnail's bottom: how far, in what colour.
    fn bar(self) -> Option<(f32, Rgba)> {
        match self {
            Progress::Proxy(f) => Some((f, t::T2)),
            Progress::Analyzing(f) => Some((f, t::AC)),
            Progress::Queued | Progress::Failed => None,
        }
    }
}

pub(crate) fn item_name(item: &MediaItem) -> String {
    item.path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| item.path.display().to_string())
}

/// `M:SS`, or `H:MM:SS` past an hour.
pub(crate) fn clock(t: Time) -> String {
    let s = t.as_secs_f64().max(0.0).round() as i64;
    if s >= 3600 {
        format!("{}:{:02}:{:02}", s / 3600, s / 60 % 60, s % 60)
    } else {
        format!("{}:{:02}", s / 60, s % 60)
    }
}
